/**
 * Normalizes an industry identifier or pathname to the canonical sector key.
 */
export function normalizeIndustryKey(industryOrPath?: string): string {
  if (!industryOrPath) return '';
  const cleaned = industryOrPath.trim().toLowerCase().replace(/ & /g, '-').replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '');
  
  // Direct match in map
  if (INDUSTRY_GOALS_MAP[cleaned]) return cleaned;

  // Path alias mapping
  const aliasMap: Record<string, string> = {
    'legal-services': 'legal',
    'medical-practices': 'healthcare',
    'medical-practices-healthcare': 'healthcare',
    'software-development': 'development',
    'software-development-devtools': 'development',
    'food-beverage': 'food',
    'chemical-specialty-materials': 'chemical',
    'chemical-sector': 'chemical',
    'transportation-fleet-operations': 'transportation',
    'transportation-logistics': 'transportation',
    'pharmaceuticals-life-sciences': 'pharma',
    'pharmaceuticals': 'pharma',
    'agriculture-agtech': 'agriculture',
    'governance-risk-compliance': 'compliance',
    'governance-compliance': 'compliance',
    'cybersecurity-secops': 'security',
    'cybersecurity': 'security',
    'human-resources-recruiting': 'hr',
    'human-resources': 'hr',
    'education-higher-ed-administration': 'education',
    'critical-infrastructure-utilities': 'utilities',
    'critical-infrastructure': 'utilities',
    'media-production-creative-studios': 'creative',
    'media-creative': 'creative',
    'field-services-contracting': 'field-services',
    'wholesale-distribution': 'wholesale-distribution',
    'geospatial-intelligence-osint': 'geospatial-intelligence',
    'emergency-management-disaster-response': 'emergency-management',
    'maritime-operations-domain-awareness': 'maritime-operations',
    'aerospace-orbital-surveillance': 'aerospace-orbital',
    'economic-commercial-spatial-intelligence': 'economic-intelligence',
  };

  if (aliasMap[cleaned] && INDUSTRY_GOALS_MAP[aliasMap[cleaned]]) {
    return aliasMap[cleaned];
  }

  // Find by substring match
  const foundKey = Object.keys(INDUSTRY_GOALS_MAP).find(k => cleaned.includes(k) || k.includes(cleaned));
  return foundKey || '';
}

/**
 * Retrieves the 9 tailored business tasks for the chosen industry sector.
 * Falls back to DEFAULT_BUSINESS_GOALS if no sector is selected or matched.
 */
export function getGoalsForIndustry(industryOrPath?: string): BusinessGoalDef[] {
  const key = normalizeIndustryKey(industryOrPath);
  if (key && INDUSTRY_GOALS_MAP[key]) {
    return INDUSTRY_GOALS_MAP[key];
  }
  return DEFAULT_BUSINESS_GOALS;
}

/**
 * Returns the top 3 default pre-selected task IDs for a given industry sector.
 */
export function getDefaultGoalsForIndustry(industryOrPath?: string): string[] {
  const goals = getGoalsForIndustry(industryOrPath);
  return goals.slice(0, 3).map(g => g.id);
}

/**
 * Flattened collection of all business goals across all sectors for O(1) lookup.
 */
export const ALL_BUSINESS_GOALS: BusinessGoalDef[] = [
  ...DEFAULT_BUSINESS_GOALS,
  ...LEGACY_BUSINESS_GOALS,
  ...Object.values(INDUSTRY_GOALS_MAP).flat(),
];
